"""Ground-truth review (no LLM): shows what upstream list_columns (GetTableCol) exposes
for every JSON table, whether alternative structures appear in it, and the answers a
naive single-path query would give (to verify each trap changes the answer)."""
import os, sys, json, sqlite3
HERE = os.path.dirname(os.path.abspath(__file__)); P0 = os.path.dirname(HERE)
ROOT = os.path.dirname(os.path.dirname(P0))
sys.path.insert(0, os.path.join(ROOT, "upstream", "FlexSQL", "src"))
from tools import create_list_columns_tool
DBS = os.path.join(P0, "fixtures", "databases")
out = ["# Ground-truth review (generated by scripts/review_ground_truth.py)\n"]
for db in sorted(os.listdir(DBS)):
    for t in sorted(f[:-5] for f in os.listdir(os.path.join(DBS, db)) if f.endswith(".json")):
        lc = create_list_columns_tool("sqlite", db, DBS)
        out.append(f"## {db}.{t} — upstream list_columns output\n```\n{lc(t)}\n```\n")
NAIVE = {
 "fleet_*: L1 naive (metrics.energy_kwh only)": ("SELECT ROUND(SUM(json_extract(r.payload,'$.metrics.energy_kwh')),2) FROM readings r JOIN devices d USING(device_id) WHERE d.site='north' AND r.recorded_at LIKE '2025-06%'", ["fleet_r00","fleet_r01","fleet_r05","fleet_r20"]),
 "fleet_*: L2 naive (payload.status only)": ("SELECT COUNT(*) FROM readings r JOIN devices d USING(device_id) WHERE d.model='TX-200' AND r.recorded_at LIKE '2025-07%' AND LOWER(json_extract(r.payload,'$.status'))='fault'", ["fleet_r00","fleet_r01","fleet_r05","fleet_r20"]),
 "H01 naive (v1 amount only)": ("SELECT ROUND(SUM(json_extract(p.payload,'$.amount')),2) FROM payment_events p JOIN merchants m USING(merchant_id) WHERE m.region='EMEA' AND json_extract(p.payload,'$.status')='succeeded' AND json_extract(p.payload,'$.currency')='USD'", ["payments"]),
 "H10 naive MAX over coalesced raw paths (no CAST)": ("SELECT MAX(COALESCE(json_extract(payload,'$.amount'), json_extract(payload,'$.amount_cents')/100.0, json_extract(payload,'$.transaction.value.amount'))) FROM payment_events WHERE LOWER(COALESCE(json_extract(payload,'$.status'),json_extract(payload,'$.state'),json_extract(payload,'$.transaction.result.status')))='succeeded' AND UPPER(COALESCE(json_extract(payload,'$.currency'),json_extract(payload,'$.currency_code'),json_extract(payload,'$.transaction.value.currency')))='USD'", ["payments"]),
 "X05 all 3 main versions but missing rare connect path": ("SELECT ROUND(SUM(COALESCE(json_extract(payload,'$.amount'), json_extract(payload,'$.amount_cents')/100.0, CAST(json_extract(payload,'$.transaction.value.amount') AS REAL))),2) FROM payment_events WHERE LOWER(COALESCE(json_extract(payload,'$.status'),json_extract(payload,'$.state'),json_extract(payload,'$.transaction.result.status')))='succeeded' AND UPPER(COALESCE(json_extract(payload,'$.currency'),json_extract(payload,'$.currency_code'),json_extract(payload,'$.transaction.value.currency')))='EUR' AND created_at>='2025-04-01'", ["payments"]),
 "X01 naive (box weight_kg only)": ("SELECT ROUND(SUM(json_extract(k.value,'$.weight_kg')),1) FROM shipments s, json_each(s.manifest,'$.packages') k WHERE s.created_at LIKE '2025-05%'", ["logistics"]),
 "X01 decoy (billable_weight_kg)": ("SELECT ROUND(SUM(json_extract(manifest,'$.billable_weight_kg')),1) FROM shipments WHERE created_at LIKE '2025-05%'", ["logistics"]),
 "X02 naive (packages[].items only)": ("SELECT SUM(json_extract(i.value,'$.qty')) FROM shipments s JOIN carriers c USING(carrier_code), json_each(s.manifest,'$.packages') k, json_each(k.value,'$.items') i WHERE c.carrier_name='FastFreight'", ["logistics"]),
 "X03 naive (events[] only)": ("SELECT COUNT(*) FROM shipments s WHERE created_at LIKE '2025-06%' AND EXISTS(SELECT 1 FROM json_each(s.tracking,'$.events') e WHERE json_extract(e.value,'$.code')='DELIVERED')", ["logistics"]),
}
out.append("## Naive single-path answers (vs gold in cases.jsonl)\n| query | db | naive answer |\n|---|---|---|")
for k, (q, dbs) in NAIVE.items():
    for db in dbs:
        c = sqlite3.connect(os.path.join(DBS, db, f"{db}.sqlite")); v = c.execute(q).fetchall(); c.close()
        out.append(f"| {k} | {db} | {v[0][0]} |")
out.append("\n## Gold\n| id | tier | gold |\n|---|---|---|")
for line in open(os.path.join(P0, "fixtures", "cases.jsonl"), encoding="utf-8"):
    c = json.loads(line); out.append(f"| {c['instance_id']} | {c['tier']} | {c['gold_rows']} |")
open(os.path.join(P0, "fixtures", "GROUND_TRUTH_REVIEW.md"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print("\n".join(out))
